mapper.sql:
AND (#{allScope}=TRUE OR c.human_agent_id=#{userId} OR l.owner_id=#{userId} OR EXISTS(SELECT 1 FROM handoffrequest own_h WHERE own_h.tenant_id=c.tenant_id AND own_h.call_session_id=c.id AND own_h.assigned_agent_id=#{userId} AND own_h.state IN ('WAITING','ACCEPTING','ACCEPTED'))
 OR EXISTS(SELECT 1 FROM ops_member m JOIN ops_member me ON me.tenant_id=m.tenant_id AND me.team_id=m.team_id AND me.is_lead=TRUE JOIN ops_team t ON t.tenant_id=m.tenant_id AND t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=c.tenant_id AND me.user_id=#{userId} AND m.user_id IN (l.owner_id,c.human_agent_id)))
AND c.id=#{id}AND c.phone LIKE CONCAT('%',#{phone},'%')
AND c.campaign_id=#{campaign_id}AND c.status=#{status}
AND c.contact_id=#{contact_id}
AND c.human_agent_id=#{agent_id}AND c.telephony_line_id=#{line_id}
AND a.intent=#{intent}AND a.review_state=#{review_state}
AND c.created_at >=#{from}AND c.created_at <=#{until}
AND TIMESTAMPDIFF(SECOND,c.started_at,c.finished_at)>=#{min_seconds}
AND TIMESTAMPDIFF(SECOND,c.started_at,c.finished_at)<=#{max_seconds}
AND (c.handoff_reason IS NOT NULL AND c.handoff_reason<>'')=#{handoff}
AND l.owner_id=#{owner_id}AND l.stage=#{stage}
AND (JSON_CONTAINS(l.tags_json,JSON_QUOTE(#{tag})) OR EXISTS(SELECT 1 FROM ops_tag_link ot WHERE ot.tenant_id=c.tenant_id AND ot.tag=#{tag} AND ((ot.target_kind='call' AND ot.object_id=c.id) OR (ot.target_kind='campaign' AND ot.object_id=CAST(c.campaign_id AS CHAR)) OR (ot.target_kind='script' AND ot.object_id=CAST(g.script_template_id AS CHAR)))))
AND EXISTS(SELECT 1 FROM ops_member tm WHERE tm.tenant_id=c.tenant_id AND tm.team_id=#{team_id} AND tm.user_id=COALESCE(l.owner_id,c.human_agent_id))

AND (#{allScope}=TRUE OR l.owner_id=#{userId} OR (#{pool}=TRUE AND l.owner_id IS NULL) OR EXISTS(SELECT 1 FROM ops_member m JOIN ops_member me ON me.tenant_id=m.tenant_id AND me.team_id=m.team_id AND me.is_lead=TRUE JOIN ops_team t ON t.tenant_id=m.tenant_id AND t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=c.tenant_id AND me.user_id=#{userId} AND m.user_id=l.owner_id))
AND c.id=#{contact_id}AND (c.phone LIKE CONCAT('%',#{keyword},'%') OR c.name LIKE CONCAT('%',#{keyword},'%'))
AND l.owner_id IS NULLAND l.owner_id=#{userId}
AND l.owner_id=#{owner_id}AND COALESCE(l.stage,'open')=#{stage}
AND l.next_at < CURRENT_TIMESTAMP(3) AND l.stage NOT IN ('completed','invalid')
AND JSON_CONTAINS(l.tags_json,JSON_QUOTE(#{tag}))
